Ext._define('judicial.pouch.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.pouch.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'sign', '-', 'search', '->', 'download'],

    sign: function() {
        var selection = this.getSelectionModel().getSelected();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'assinando itens...'});

        mask.show();
        this.factoryRestful().sign(
            selection.get('pk'),
            {
                scope: this,
                fn: function() {
                    this.getStore().reload();
                }
            },
            {
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Assinado',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {fn: function() { mask.hide(); }}
        );
    },

    getSignAction: function(cfg) {
        if(!this._signAction)
            this._signAction = Ext._create('Ext.Button', {
                text: 'Assinar',
                scope: this,
                handler: this.sign
            });

        return this._signAction;
    },

    renderer_done: function(value, cell, data) {
        if(data.get('signed_by'))
            return [
                '<div>',
                    data.get('items_done'),
                    ' de ',
                    data.get('items_count'),
                '</div>'
            ].join('');
        else
        return [
            '<div>Lote não assinado</div>'
        ].join('');
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Número', dataIndex: 'cache_number', width: 70},
                    {header: 'Descrição', dataIndex: 'unicode', id: 'autoExpandColumn'},
                    {header: 'Movimentado', dataIndex: '__ghost_1__', width: 120, renderer: this.renderer_done},
                    {header: 'Origem', dataIndex: 'from_location_unicode', width: 300},
                    {header: 'Destino', dataIndex: 'to_location_unicode', width: 300},
                    {header: 'Assinado', dataIndex: 'signed_by_unicode', width: 140},
                    {header: 'Data assinatura', dataIndex: 'signed_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {hidden: true, header: 'Criado', dataIndex: 'created_by_unicode', width: 140},
                    {hidden: true, header: 'Data criação', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {hidden: true, header: 'Modificado', dataIndex: 'modified_by_unicode', width: 140},
                    {hidden: true, header: 'Data de modificação', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'judicial.pouch.Restful',
    'judicial.pouch.Grid'
);
